fn tok(tokens: List[Str], i: Int) -> Str {
  return tokens.get_or(i, "")
}

fn is_name(t: Str) -> Bool {
  if t.is_empty() {
    return false
  }
  return t.chars().all(fn(c) => "abcdefghijklmnopqrstuvwxyz".contains(c))
}

fn body_of(t: Str) -> Str {
  if t.starts_with("-") {
    return t.slice(1, t.len())
  }
  return t
}

fn is_number(t: Str) -> Bool {
  let body = body_of(t)
  if body.is_empty() {
    return false
  }
  return body.chars().all(fn(c) => "0123456789".contains(c))
}

fn is_term(t: Str) -> Bool {
  return is_name(t) or is_number(t)
}

fn is_op(t: Str) -> Bool {
  return (t == "+") or (t == "-")
}

fn syntax_ok(tokens: List[Str]) -> Bool {
  let n = tokens.len()
  if n < 3 or n % 2 == 0 {
    return false
  }
  if not is_name(tok(tokens, 0)) {
    return false
  }
  if tok(tokens, 1) != "=" {
    return false
  }
  if not is_term(tok(tokens, 2)) {
    return false
  }
  return range(3, n).all(fn(i) => ((i % 2 == 1) and is_op(tok(tokens, i))) or ((i % 2 == 0) and is_term(tok(tokens, i))))
}

fn term_value(vars: Map[Str, Int], t: Str) -> Result[Int, Str] {
  if is_number(t) {
    let negative = t.starts_with("-")
    let magnitude = body_of(t).to_int().unwrap_or(0)
    let sign = match negative {
      true => -1,
      false => 1,
    }
    return Ok(sign * magnitude)
  }
  if not vars.has(t) {
    return Err("undefined " + t)
  }
  return Ok(vars.get(t).unwrap_or(0))
}

fn fold_pairs(vars: Map[Str, Int], tokens: List[Str], i: Int, acc: Int) -> Result[Int, Str] {
  if i >= tokens.len() {
    return Ok(acc)
  }
  let v = term_value(vars: vars, t: tok(tokens, i + 1))?
  let next = match tok(tokens, i) == "+" {
    true => acc + v,
    false => acc - v,
  }
  return fold_pairs(vars: vars, tokens: tokens, i: i + 2, acc: next)
}

fn run_line(vars: Map[Str, Int], line: Str) -> Result[Map[Str, Int], Str] {
  let tokens = line.split(" ")
  if not syntax_ok(tokens) {
    return Err("syntax error")
  }
  let first = term_value(vars: vars, t: tok(tokens, 2))?
  let total = fold_pairs(vars: vars, tokens: tokens, i: 3, acc: first)?
  return Ok(vars.set(tok(tokens, 0), total))
}

fn run_all(lines: List[Str], vars: Map[Str, Int]) -> Result[Map[Str, Int], Str] {
  if lines.is_empty() {
    return Ok(vars)
  }
  let next = run_line(vars: vars, line: lines.first().unwrap_or(""))?
  return run_all(lines: lines.drop(1), vars: next)
}

pub fn run_vars(lines: List[Str]) -> Result[Map[Str, Int], Str] {
  let empty: Map[Str, Int] = Map {}
  return run_all(lines: lines, vars: empty)
}
